local CatBallUtils = import("Game.CatBall.CatBallUtils")

---
---@class OverseaChatSystemPanel
local OverseaChatSystemPanel = Class('OverseaChatSystemPanel')

---@type Social
local Social = AppService:GetInstance():GetSocialLine()

function OverseaChatSystemPanel:__init()
    ---@type SuperScrollView.LoopGridView
    self.listView = nil
    self.handler = nil
    self.data = nil
end

function OverseaChatSystemPanel:__delete()
    self.listView = nil
    self.handler = nil
    self.data = nil
end

function OverseaChatSystemPanel:Awake()
    ---@type SuperScrollView.LoopGridView
    self.listView = KTool.GetComponent(self.controller.transform:Find("ScrollView").gameObject, typeof(LoopGridView))
    self.handler = Events.AddListener(ChatConstants.EventNames.NEW_SYSTEM_MESSAGE, function(data)
        local social = AppService:GetInstance():GetSocialLine()
        self.data = social.systemData
        self:FreshListView(self.data)
    end)
end

function OverseaChatSystemPanel:FreshListView(data)
    if isNull(self.listView) then
      return
    end
    if not self.listView.IsListViewInit then
        self.listView:InitGridView(#data, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.listView, #data)
    end
    if #self.data > 0 then
        self.listView:MovePanelToItemByIndex(#self.data - 1)
    end
end

---OnGetItemByIndex
---@param gridView SuperScrollView.LoopGridView
---@param index number
---@param row number
---@param column number
function OverseaChatSystemPanel:OnGetItemByIndex(gridView, index, row, column)
    if index < 0 then
        return
    end
    local position = index + 1
    local data = self.data[position]
    if not data then
        return
    end

    local cell = gridView:NewListViewItem(PrefabCellName)
    local textDesc = cell.transform:Find("TextDesc")
    local textPic = textDesc.transform:GetComponent(typeof(TextPic))
    local hyperlink = textDesc.transform:GetComponent(typeof(Hyperlink))
    if data.systemType == ChatConstants.ChatSystemMsgType.ASYNC_PVP_RANK_DOWN or
    data.systemType == ChatConstants.ChatSystemMsgType.ASYNC_PVP_SINGLE_RANK_DOWN then
        local btnText = localize('去查看')
        textPic.text = string.format("%s<a href=%d>[%s]</a>", Social:ConvertSystemMessage(data) or '', data.systemType, btnText)
    else
        textPic.text = Social:ConvertSystemMessage(data) or ''
    end
    hyperlink.HyperlinkAction = Bind(self, self.HyperlinkOnClickHandler)
    return cell
end

function OverseaChatSystemPanel:HyperlinkOnClickHandler(systemType)
    if BattleViewMgr then
        GameUtils.Toast(localize("战斗中无法跳转"))
        return
    end
    local type = checkInt(systemType)
    local id = nil
    local systemName = nil
    if type == ChatConstants.ChatSystemMsgType.ASYNC_PVP_RANK_DOWN then
        id = Constants.UITypeIds.LadderStruggleMainDialog
        systemName = Constants.SystemToggleIds.Id2007
    elseif type == ChatConstants.ChatSystemMsgType.ASYNC_PVP_SINGLE_RANK_DOWN then
        id = Constants.UITypeIds.LadderStruggleSingleMainDialog
        systemName = Constants.SystemToggleIds.Id2017
    end

    GameUtils.ShowBlackOverlay(nil, function ()
        cs_coroutine.yield_return(UIModule.OpenDialog(
                { id = id, parameters = {systemName = systemName} },
                { { id = Constants.UITypeIds.UIHomeView } }
        ))
        Events.Broadcast(ChatConstants.EventNames.OVERSEA_CLOSE_CHAT_DIALOG)
    end)
    
