function OverseaChatSystemPanel:OnDisable()
    ---防止占内存，清理一次
    self:FreshListView({})
end

function OverseaChatSystemPanel:OnEnable()
    ---@type Social
    local socialLine = AppService:GetInstance():GetSocialLine()
    self.data = socialLine.systemData
    self:FreshListView(self.data)
end

function OverseaChatSystemPanel:Refresh(env)
    ---@type SuperScrollView.LoopGridView
    self.listView = KTool.GetComponent(self.controller.transform:Find("ScrollView").gameObject, typeof(LoopGridView))
end

function OverseaChatSystemPanel:OnDestroy()
    Events.RemoveListener(ChatConstants.EventNames.NEW_SYSTEM_MESSAGE, self.handler)
    self.controller = nil--luabehaviour 中CSharp对象
    self.handler = nil
    self:Delete()
    self = nil
end

return OverseaChatSystemPanel